<?php declare(strict_types=1); namespace Annam; $available=$product['active'] && ($product['available']??true) && (!isset($product['qty_limit']) || $product['qty_limit']===null || $product['qty_sold']<$product['qty_limit']); ?>
<li class="dish"><a class="dish-img" href="/item/<?= e($product['id']) ?>/"><?php if ($product['image']): ?><img src="<?= e(image_url($product['image'])) ?>" alt="<?= e($product['name']) ?>" loading="lazy" width="400" height="300"><?php else: ?><span class="php-photo-empty">Photo coming soon</span><?php endif; ?></a><div class="dish-info"><h3><a href="/item/<?= e($product['id']) ?>/"><?= e($product['name']) ?></a></h3><div class="dish-buy"><span class="price"><?= money($product['effective_price']??$product['price']) ?></span>
<?php if ($available && ($product['fulfilment']==='courier' || isset($slotId))): ?><form method="post" action="/cart/add/"><?= csrf() ?><input type="hidden" name="item_id" value="<?= e($product['id']) ?>"><?php if ($product['fulfilment']==='scheduled'): ?><input type="hidden" name="slot_id" value="<?= e($slotId) ?>"><input type="hidden" name="date" value="<?= e($date) ?>"><?php endif; ?><button class="btn btn-add" type="submit">Add</button></form><?php elseif (!$available): ?><span class="php-muted">Unavailable</span><?php else: ?><a class="btn" href="/menu/">Choose meal</a><?php endif; ?></div></div></li>
